@Serializable(with = ParsedCommandSerializer::class)
public sealed interface ParsedCommand

@Serializable
public data class ParsedCommandReadParsedCommand(
    @SerialName("cmd")
    public val cmd: String,
    @SerialName("name")
    public val name: String,
    @SerialName("path")
    public val path: String,
    @SerialName("type")
    public val type: String = "read",
) : ParsedCommand {
    init { require(type == "read") }
}

@Serializable
public data class ParsedCommandListFilesParsedCommand(
    @SerialName("cmd")
    public val cmd: String,
    @SerialName("path")
    public val path: String? = null,
    @SerialName("type")
    public val type: String = "list_files",
) : ParsedCommand {
    init { require(type == "list_files") }
}

@Serializable
public data class ParsedCommandSearchParsedCommand(
    @SerialName("cmd")
    public val cmd: String,
    @SerialName("path")
    public val path: String? = null,
    @SerialName("query")
    public val query: String? = null,
    @SerialName("type")
    public val type: String = "search",
) : ParsedCommand {
    init { require(type == "search") }
}

@Serializable
public data class ParsedCommandUnknownParsedCommand(
    @SerialName("cmd")
    public val cmd: String,
    @SerialName("type")
    public val type: String = "unknown",
) : ParsedCommand {
    init { require(type == "unknown") }
}

public object ParsedCommandSerializer : JsonContentPolymorphicSerializer<ParsedCommand>(ParsedCommand::class) {
    override fun selectDeserializer(element: JsonElement): DeserializationStrategy<ParsedCommand> =
        when (element.jsonObject["type"]?.jsonPrimitive?.content) {
            "read" -> ParsedCommandReadParsedCommand.serializer()
            "list_files" -> ParsedCommandListFilesParsedCommand.serializer()
            "search" -> ParsedCommandSearchParsedCommand.serializer()
            "unknown" -> ParsedCommandUnknownParsedCommand.serializer()
            else -> error("Unknown ParsedCommand type")
        }
}

